1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.util.ArrayList;
5	import java.util.List;
6	
7	import net.officefloor.plugin.variable.Out;
8	import org.springframework.samples.petclinic.model.OwnerRegion;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.web.bind.annotation.RequestBody;
11	
12	/**
13	 * Rejects a create request that is missing or blank in any required owner field.
14	 *
15	 * <p>Runs first in the {@code POST /api/owners} pipeline. It binds the body once (this is the only
16	 * step that reads {@code @RequestBody}) and republishes it for {@link BuildOwner}. firstName,
17	 * lastName, city and telephone must be present and non-blank, and an address must be supplied in
18	 * either the structured form (a non-blank addressLine1, with an optional addressLine2) or the flat
19	 * 'address' form; any missing field is collected and reported together via
20	 * {@link OwnerFieldsInvalidException}. A supplied registrationDate must not be later than the
21	 * server's current date.
22	 *
23	 * <p>The telephone is converted to E.164 form (see {@link OwnerTelephone#toE164}). The E.164 value
24	 * replaces the submitted one on the republished body, so it is what gets stored and returned. A
25	 * number that cannot form valid E.164 is rejected as an invalid {@code telephone}.
26	 */
27	public class ValidateOwnerFields {
28	
29	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
30	            throws OwnerFieldsInvalidException {
31	        List<String> errors = new ArrayList<>();
32	        if (isBlank(request.getFirstName())) {
33	            errors.add("firstName");
34	        }
35	        if (isBlank(request.getLastName())) {
36	            errors.add("lastName");
37	        }
38	        // The address may be supplied in a structured form (addressLine1 plus an optional
39	        // addressLine2) or the flat 'address' form; the structured form is preferred when present.
40	        // Each supplied field is normalized (whitespace collapsed, upper-cased, abbreviations
41	        // expanded). An owner is valid when it supplies an address in EITHER form — a non-blank
42	        // addressLine1 or a non-blank flat address — so earlier minimal (flat) owners stay accepted.
43	        // The normalized values replace the submitted ones, so they are what get stored, returned
44	        // and (via the composed 'address') compared; the composed 'address' is the normalized
45	        // addressLine1 with the normalized addressLine2 appended after a single space when present.
46	        String addressLine1 = OwnerAddress.normalize(request.getAddressLine1());
47	        String flatAddress = OwnerAddress.normalize(request.getAddress());
48	        if (!addressLine1.isEmpty()) {
49	            String addressLine2 = OwnerAddress.normalize(request.getAddressLine2());
50	            request.setAddressLine1(addressLine1);
51	            request.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
52	            request.setAddress(OwnerAddress.compose(addressLine1, addressLine2));
53	        }
54	        else if (!flatAddress.isEmpty()) {
55	            request.setAddressLine1(null);
56	            request.setAddressLine2(null);
57	            request.setAddress(flatAddress);
58	        }
59	        else {
60	            errors.add("address");
61	        }
62	        if (isBlank(request.getCity())) {
63	            errors.add("city");
64	        }
65	        if (isBlank(request.getTelephone())) {
66	            errors.add("telephone");
67	        }
68	        else {
69	            String telephone = OwnerTelephone.toE164(request.getTelephone());
70	            if (telephone == null) {
71	                errors.add("telephone");
72	            }
73	            else {
74	                request.setTelephone(telephone);
75	            }
76	        }
77	        // Email is optional. When present it must be syntactically valid and its domain must not be a
78	        // known disposable provider; it is normalized to lower case so it is stored and returned
79	        // lower-cased.
80	        String email = request.getEmail();
81	        if (email != null) {
82	            if (!OwnerEmail.isValid(email) || OwnerEmail.isDisposable(email)) {
83	                errors.add("email");
84	            }
85	            else {
86	                request.setEmail(OwnerEmail.normalize(email));
87	            }
88	        }
89	        // Postcode is optional. When present it must be exactly four digits and, for a city with a
90	        // known region, fall within that region's postcode range; a city with no known region
91	        // accepts any 4-digit postcode. An absent postcode leaves the owner backward-compatible.
92	        String postcode = request.getPostcode();
93	        if (postcode != null && !OwnerRegion.isPostcodeValid(request.getCity(), postcode)) {
94	            errors.add("postcode");
95	        }
96	        // Registration date is optional and defaults to the server date when omitted. When supplied
97	        // it may not be in the future: a date later than the server's current date is rejected.
98	        LocalDate registrationDate = request.getRegistrationDate();
99	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
100	            errors.add("registrationDate");
101	        }
102	        if (!errors.isEmpty()) {
103	            throw new OwnerFieldsInvalidException(errors);
104	        }
105	        validated.set(request);
106	    }
107	
108	    private static boolean isBlank(String value) {
109	        return value == null || value.isBlank();
110	    }
111	}
